HEADER = """package com.ascent.climb.data.i18n

/**
 * %s
 *
 * 由 `tools/i18n/gen_hike_packs_lang.py` 生成，不要手改。
 */
val %s: Map<String, String> = mapOf(
"""


def emit(out_path, val_name, doc, rows, intro=None):
    lines = [HEADER % (doc, val_name)]
    items = []
    for rid, (name, area, brief) in rows.items():
        for suffix, text in (("name", name), ("area", area), ("brief", brief)):
            items.append('    "hike.%s.%s" to "%s"' % (rid, suffix, text.replace('"', '\\"')))
        if intro and intro.get(rid):
            items.append('    "hike.%s.intro" to "%s"' % (rid, intro[rid].replace('"', '\\"')))
    lines.append(",\n".join(items))
    lines.append("\n)\n")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("".join(lines))
    return len(items)


def main():
    want = sys.argv[1:] or list(LANGS.keys())
    for lang in want:
        if lang not in LANGS:
            print("unknown", lang)
            continue
        item = LANGS[lang]
        val, fname, doc, rows = item[:4]
        intro = item[4] if len(item) > 4 else None
        n = emit(os.path.join(OUT_DIR, fname), val, doc, rows, intro)
        print("%s -> %s  %d keys / %d routes (intro %d)" % (
            lang, fname, n, len(rows), len(intro) if intro else 0))


if __name__ == "__main__":
    main()
